//! What makes an [`InMemoryVolume`](super::InMemoryVolume) behave like ONE real
//! device when asked to (the browser demo does): what a file holds, how fast the
//! device streams it, and how often it lets the caller's thread breathe. Every
//! part is off unless its builder option is set, so the tests that only care
//! about bytes see the store they always did.
//!
//! - **Content**: a file holds real bytes or a [`InMemoryContent::Synthetic`]
//!   descriptor, "`len` generated bytes from `seed`". Generated bytes are a PURE
//!   function of `(seed, offset)` (counter mode), so a positioned read anywhere
//!   answers the same bytes a stream does, and 3.6 GB of demo photos cost a few
//!   bytes each. A write keeps a descriptor when every byte it was handed is what
//!   one would generate ([`ContentSink`]), so a copy of a synthetic file stays
//!   synthetic without the read and write halves sharing anything but bytes.
//! - **Bandwidth** ([`Bandwidth`]): one budget for the whole volume, which every
//!   read stream draws its chunks from, as one disk splits its throughput
//!   between readers.
//! - **Yielding** ([`Yielder`]): every call hands the thread back once a slice
//!   has passed since the last time, like a device whose every call waits on I/O.
//!   In the browser that's what lets the page paint and take input mid-operation.
//!
//! Positioned reads (`read_range`, the viewer's random access) are never paced:
//! the viewer bridges sync-over-async on an in-memory volume by polling once.

use std::path::Path;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use crate::ignore_poison::{IgnorePoison, RwLockIgnorePoison};
use crate::rt;

/// What an in-memory file holds.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum InMemoryContent {
    /// Real bytes, as written.
    Bytes(Arc<Vec<u8>>),
    /// `len` bytes generated from `seed`, never stored.
    Synthetic {
        /// Which bytes: every seed generates a different sequence.
        seed: u64,
        /// How many.
        len: u64,
    },
}

impl InMemoryContent {
    /// Real bytes.
    pub fn bytes(data: impl Into<Vec<u8>>) -> Self {
        Self::Bytes(Arc::new(data.into()))
    }

    /// `len` generated bytes from `seed`.
    pub fn synthetic(seed: u64, len: u64) -> Self {
        Self::Synthetic { seed, len }
    }

    /// How many bytes the file holds.
    pub fn len(&self) -> u64 {
        match self {
            Self::Bytes(data) => data.len() as u64,
            Self::Synthetic { len, .. } => *len,
        }
    }

    /// Whether the file is empty.
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Up to `len` bytes from `offset` (fewer at the end, none past it).
    pub fn read_at(&self, offset: u64, len: usize) -> Vec<u8> {
        let end = offset.saturating_add(len as u64).min(self.len());
        if offset >= end {
            return Vec::new();
        }
        match self {
            Self::Bytes(data) => data[offset as usize..end as usize].to_vec(),
            Self::Synthetic { seed, .. } => generated(*seed, offset, (end - offset) as usize),
        }
    }
}

/// splitmix64's golden-ratio increment: the generator's counter step.
const GOLDEN: u64 = 0x9E37_79B9_7F4A_7C15;
const MIX_A: u64 = 0xBF58_476D_1CE4_E5B9;
const MIX_B: u64 = 0x94D0_49BB_1331_11EB;

/// splitmix64's finalizer: a bijection on `u64`, so [`unmix`] can invert it.
fn mix(mut z: u64) -> u64 {
    z = (z ^ (z >> 30)).wrapping_mul(MIX_A);
    z = (z ^ (z >> 27)).wrapping_mul(MIX_B);
    z ^ (z >> 31)
}

/// The multiplicative inverse of an odd `a` modulo 2^64 (Newton's iteration).
const fn inverse(a: u64) -> u64 {
    let mut x = a;
    let mut i = 0;
    while i < 6 {
        x = x.wrapping_mul(2u64.wrapping_sub(a.wrapping_mul(x)));
        i += 1;
    }
    x
}

/// Undoes `z ^ (z >> shift)`.
fn unshift(z: u64, shift: u32) -> u64 {
    let mut x = z;
    let mut s = shift;
    while s < 64 {
        x = z ^ (x >> shift);
        s += shift;
    }
    x
}

/// The inverse of [`mix`].
fn unmix(z: u64) -> u64 {
    let z = unshift(z, 31);
    let z = unshift(z.wrapping_mul(inverse(MIX_B)), 27);
    unshift(z.wrapping_mul(inverse(MIX_A)), 30)
}

/// Word `index` of `seed`'s sequence (little-endian bytes on the wire).
fn word(seed: u64, index: u64) -> u64 {
    mix(seed.wrapping_add(index.wrapping_mul(GOLDEN)))
}

/// `len` generated bytes of `seed`'s sequence from `offset`: a pure function, so
/// any reader at any offset sees the same bytes.
fn generated(seed: u64, offset: u64, len: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(len);
    let mut at = offset;
    let end = offset + len as u64;
    while at < end {
        let bytes = word(seed, at / 8).to_le_bytes();
        let from = (at % 8) as usize;
        let take = ((end - at) as usize).min(8 - from);
        out.extend_from_slice(&bytes[from..from + take]);
        at += take as u64;
    }
    out
}

/// Collects what a write is handed and answers what to store: the descriptor
/// those bytes are, when they all are one, else the bytes.
///
/// The seed comes from the bytes themselves (word 0 is `mix(seed)`, and `mix` is
/// a bijection), so nothing but the bytes crosses from the reader to the writer.
/// Every later byte is checked against that seed's sequence; ❗ one byte off and
/// the write keeps real bytes from the start, so an edited file can never come
/// back as generated content.
// DEFAULT-OK: a sink that was handed nothing yet holds nothing, which is the truth.
#[derive(Default)]
pub(crate) struct ContentSink {
    state: SinkState,
}

// DEFAULT-OK: no bytes seen yet is the honest start of every write.
#[derive(Default)]
enum SinkState {
    /// Fewer than eight bytes so far: no seed to check against yet.
    #[default]
    Empty,
    Probing(Vec<u8>),
    /// Every byte so far is `seed`'s, `len` of them.
    Matching {
        seed: u64,
        len: u64,
    },
    Bytes(Vec<u8>),
}

impl ContentSink {
    /// Takes the next chunk.
    pub(crate) fn push(&mut self, chunk: &[u8]) {
        self.state = match std::mem::take(&mut self.state) {
            SinkState::Empty => Self::probe(chunk.to_vec()),
            SinkState::Probing(mut held) => {
                held.extend_from_slice(chunk);
                Self::probe(held)
            }
            SinkState::Matching { seed, len } => {
                if chunk == generated(seed, len, chunk.len()).as_slice() {
                    SinkState::Matching {
                        seed,
                        len: len + chunk.len() as u64,
                    }
                } else {
                    let mut bytes = generated(seed, 0, len as usize);
                    bytes.extend_from_slice(chunk);
                    SinkState::Bytes(bytes)
                }
            }
            SinkState::Bytes(mut bytes) => {
                bytes.extend_from_slice(chunk);
                SinkState::Bytes(bytes)
            }
        };
    }

    fn probe(held: Vec<u8>) -> SinkState {
        let Some(first) = held.first_chunk::<8>() else {
            return SinkState::Probing(held);
        };
        let seed = unmix(u64::from_le_bytes(*first));
        if held == generated(seed, 0, held.len()) {
            SinkState::Matching {
                seed,
                len: held.len() as u64,
            }
        } else {
            SinkState::Bytes(held)
        }
    }

    /// What to store.
    pub(crate) fn finish(self) -> InMemoryContent {
        match self.state {
            SinkState::Empty => InMemoryContent::bytes(Vec::new()),
            SinkState::Probing(bytes) | SinkState::Bytes(bytes) => InMemoryContent::bytes(bytes),
            SinkState::Matching { seed, len } => InMemoryContent::synthetic(seed, len),
        }
    }
}

/// How late a timer may wake (tokio's resolution is a millisecond, a page's
/// `setTimeout` a few) and still count as "straight back" for [`Bandwidth`].
const TIMER_SLACK: Duration = Duration::from_millis(5);

/// One device's throughput, shared by every stream on the volume: each chunk
/// books the next free slot on the device's timeline and waits for its end, so
/// three concurrent readers each get a third of the rate, as on one disk.
#[derive(Debug)]
pub(crate) struct Bandwidth {
    bytes_per_sec: u64,
    /// When the device is next free; `None` until the first read.
    free_at: Mutex<Option<rt::time::Instant>>,
}

impl Bandwidth {
    pub(crate) fn new(bytes_per_sec: u64) -> Self {
        Self {
            bytes_per_sec: bytes_per_sec.max(1),
            free_at: Mutex::new(None),
        }
    }

    /// Waits until the device has moved `bytes` for this caller. Dropping the
    /// wait (a cancel) gives the caller back at once; the slot it booked stays
    /// spent, as a disk's read-ahead would.
    pub(crate) async fn transfer(&self, bytes: usize) {
        let takes = Duration::from_nanos((bytes as u128 * 1_000_000_000 / u128::from(self.bytes_per_sec)) as u64);
        let done = {
            let mut free_at = self.free_at.lock_ignore_poison();
            let now = rt::time::now();
            // A reader that comes straight back for its next chunk continues the
            // device's timeline: timers wake up to a millisecond late, and starting
            // from `now` would add that lateness to every chunk.
            let start = match *free_at {
                Some(free) if free + TIMER_SLACK >= now => free,
                _ => now,
            };
            let done = start + takes;
            *free_at = Some(done);
            done
        };
        rt::time::sleep_until(done).await;
    }
}

/// Hands the caller's thread back once `slice` has passed since it last did.
#[derive(Debug)]
pub(crate) struct Yielder {
    slice: Duration,
    last: Mutex<rt::Instant>,
}

impl Yielder {
    pub(crate) fn new(slice: Duration) -> Self {
        Self {
            slice,
            last: Mutex::new(rt::now()),
        }
    }

    /// Yields when the slice is spent; otherwise returns without pending.
    pub(crate) async fn breathe(&self) {
        let due = {
            let mut last = self.last.lock_ignore_poison();
            if rt::since(*last) >= self.slice {
                *last = rt::now();
                true
            } else {
                false
            }
        };
        if due {
            rt::task::yield_now().await;
        }
    }
}

/// The device knobs, and the helpers the `Volume` impl calls them through.
impl super::InMemoryVolume {
    /// Streams every read at `bytes_per_sec`, shared by all of this volume's
    /// readers at once ([`Bandwidth`]). Positioned reads stay at memory speed.
    pub fn with_bandwidth(mut self, bytes_per_sec: u64) -> Self {
        self.bandwidth = Some(Arc::new(Bandwidth::new(bytes_per_sec)));
        self
    }

    /// Hands the caller's thread back once `slice` has passed since the last
    /// time, at every call and every streamed chunk ([`Yielder`]).
    pub fn with_yielding(mut self, slice: Duration) -> Self {
        self.yielder = Some(Arc::new(Yielder::new(slice)));
        self
    }

    /// Gives the volume `total_bytes` of room: free space is that minus what the
    /// files hold, read live, and a write that wouldn't fit is refused
    /// `StorageFull` before it reads a byte.
    pub fn with_capacity(mut self, total_bytes: u64) -> Self {
        self.capacity = Some(total_bytes);
        self
    }

    /// Puts `content` in the file at `path` (which must already be an entry),
    /// and makes its size say so.
    ///
    /// # Panics
    ///
    /// When `path` isn't a file this volume holds: a builder mistake.
    pub fn with_content(self, path: impl AsRef<Path>, content: InMemoryContent) -> Self {
        {
            let normalized = self.normalize(path.as_ref());
            let mut entries = self.entries.write_ignore_poison();
            let entry = entries
                .get_mut(&normalized)
                .filter(|entry| !entry.metadata.is_directory)
                .unwrap_or_else(|| panic!("with_content: no file at {}", normalized.display()));
            entry.metadata.size = Some(content.len());
            entry.content = Some(content);
        }
        self
    }

    /// One breath at a call boundary: a no-op unless [`Self::with_yielding`].
    pub(super) async fn breathe(&self) {
        if let Some(yielder) = &self.yielder {
            yielder.breathe().await;
        }
    }

    /// The bytes every file holds, for [`Self::with_capacity`]'s free space.
    pub(super) fn stored_bytes(&self) -> u64 {
        self.entries
            .read_ignore_poison()
            .values()
            .filter(|entry| !entry.metadata.is_directory)
            .map(|entry| entry.content.as_ref().map_or(0, InMemoryContent::len))
            .sum()
    }

    /// The space answer under [`Self::with_capacity`], else `None`.
    pub(super) fn capacity_space(&self) -> Option<crate::volume::SpaceInfo> {
        let total = self.capacity?;
        Some(crate::volume::SpaceInfo::bounded(
            total,
            total.saturating_sub(self.stored_bytes()),
        ))
    }

    /// Refuses a write of `incoming` bytes that wouldn't fit.
    pub(super) fn check_room_for(&self, incoming: u64) -> Result<(), crate::volume::VolumeError> {
        match self.capacity {
            Some(total) if self.stored_bytes().saturating_add(incoming) > total => {
                Err(crate::volume::VolumeError::StorageFull {
                    message: "the in-memory volume is full".into(),
                })
            }
            _ => Ok(()),
        }
    }

    /// Puts a new file holding `content` at `path`, refusing a taken name (as
    /// `create_file` does): the landing of a streamed write.
    pub(super) fn create_content(
        &self,
        path: &Path,
        content: InMemoryContent,
    ) -> Result<(), crate::volume::VolumeError> {
        let normalized = self.normalize(path);
        let mut entries = self.entries.write_ignore_poison();
        if entries.contains_key(&normalized) {
            return Err(crate::volume::VolumeError::AlreadyExists(
                normalized.display().to_string(),
            ));
        }
        Self::insert_file(&mut entries, normalized, content);
        Ok(())
    }

    /// The device's bandwidth, for a read stream to draw from.
    pub(super) fn bandwidth(&self) -> Option<Arc<Bandwidth>> {
        self.bandwidth.clone()
    }

    /// The device's yielder, for a read stream to breathe through.
    pub(super) fn yielder(&self) -> Option<Arc<Yielder>> {
        self.yielder.clone()
    }
}

